attributes.gen_ai.tool.call.result:
[{"content": {"text": "{
  "matches": [
    {
      "id": "tool:bash",
      "kind": "tool",
      "name": "bash",
      "description": "Execute a command in the shell and return combined stdout/stderr.",
      "status": "ready",
      "input_schema": {
        "type": "object",
        "properties": {
          "command": {
            "type": "string",
            "description": "Shell command to execute"
          },
          "description": {
            "type": "string",
            "description": "Optional short name for this call, in the user's language, shown in task lists."
          },
          "run_in_background": {
            "type": "boolean",
            "description": "Run detached: returns a job id immediately and keeps running across turns (no foreground timeout). Read new output with bash_output, wait with wait, stop it with kill_shell. Use for long-running commands like servers, watchers, or builds you don't need to block on."
          },
          "preserve_background_processes": {
            "type": "boolean",
            "description": "After the shell command exits normally, keep any process-group members it intentionally left behind. Use only for deliberate daemonization, browser/GUI/session launchers such as playwright-cli open, or nohup/disown/setsid; cancellation and timeouts still kill the process group."
          },
          "timeout_seconds": {
            "type": "integer",
            "description": "Deadline for this foreground call. Only tightens the host cap — a larger value is clamped to it. Output collected before the deadline is still returned, so set it low when a command's cost is unpredictable (a broad filesystem walk, a network fetch) instead of paying the full cap to find out. For work that legitimately runs long, use run_in_background.",
            "minimum": 1
          },
          "verifies": {
            "type": "string",
            "description": "Name what this call decides (e.g. \"balances.json keys are sorted\") to record it as a check. The exit status becomes the verdict, so the command must be one command or an \u0026\u0026 chain; a ';', a pipe, or '||' hands the status to something else and the call is refused."
          }
        },
        "required": [
          "command"
        ]
      }
    },
    {
      "id": "tool:use_capability",
      "kind": "tool",
      "name": "use_capability",
      "description": "Search and call deferred tools, skills, and MCP through stable IDs such as tool:grep, skill:review, task:subagent, task:fleet, and mcp-tool:server/tool.",
      "status": "ready",
      "read_only": true,
      "input_schema": {
        "type": "object",
        "properties": {
          "action": {
            "type": "string",
            "description": "search | list | inspect | call | decline"
          },
          "query": {
            "type": "string",
            "description": "Natural-language search goal"
          },
          "limit": {
            "type": "integer",
            "minimum": 1,
            "maximum": 20,
            "description": "Result limit; default 5"
          },
          "capability_id": {
            "type": "string",
            "description": "Stable ID required by inspect, call, and decline"
          },
          "arguments": {
            "type": "object",
            "description": "Target arguments for call"
          },
          "reason": {
            "type": "string",
            "description": "Non-empty decline reason"
          }
        },
        "required": [
          "action"
        ]
      }
    },
    {
      "id": "tool:kill_shell",
      "kind": "tool",
      "name": "kill_shell",
      "description": "Terminate a running background job (bash or task) started with run_in_background.",
      "status": "ready",
      "input_schema": {
        "type": "object",
        "properties": {
          "job_id": {
            "type": "string",
            "description": "The background job id to terminate (e.g. \"bash-1\")."
          }
        },
        "required": [
          "job_id"
        ]
      }
    },
    {
      "id": "tool:read_subagent_result",
      "kind": "tool",
      "name": "read_subagent_result",
      "description": "Read a completed sub-agent's full final answer by the Subagent reference returned from task, parallel_tasks, or fleet.",
      "status": "ready",
      "read_only": true,
      "input_schema": {
        "type": "object",
        "properties": {
          "ref": {
            "type": "string",
            "description": "The sa_... value from a Subagent reference line."
          },
          "offset_bytes": {
            "type": "integer",
            "description": "UTF-8 byte offset to start reading from. Omit for the beginning; use next_offset_bytes from the previous page.",
            "minimum": 0
          },
          "limit_bytes": {
            "type": "integer",
            "description": "Maximum UTF-8 bytes to return. Defaults to 12288 and is capped at 24576.",
            "minimum": 1,
            "maximum": 24576
          }
        },
        "required": [
          "ref"
        ]
      }
    },
    {
      "id": "tool:slash_command",
      "kind": "tool",
      "name": "slash_command",
      "description": "Invoke a project slash command (a reusable prompt template or skill) by name.",
      "status": "ready",
      "read_only": true,
      "input_schema": {
        "type": "object",
        "properties": {
          "command": {
            "type": "string",
            "description": "Slash command name (with or without a leading slash). Empty or \"list\" returns the available commands."
          },
          "arguments": {
            "type": "string",
            "description": "Arguments passed to the command, as you'd type them after the name (space-separated)."
          }
        }
      }
    }
  ],
  "note": "Call action=call with a returned capability id. An empty matches array means this catalog search found no lexical match; it does not prove that every possible external capability is unavailable.",
  "query": "run shell command in sandbox inspect file bytes"
}", "type": "text"}, "type": "content"}]

[{"content": {"text": "{
  "matches": [
    {
      "id": "tool:conclude_blocked",
      "kind": "tool",
      "name": "conclude_blocked",
      "description": "Declare that part of the task cannot be completed as specified, after you have established why.",
      "status": "ready",
      "read_only": true,
      "input_schema": {
        "type": "object",
        "properties": {
          "blocker": {
            "type": "string",
            "description": "What cannot be done and why it cannot. Shown to the user."
          },
          "criterion_id": {
            "type": "string",
            "description": "Optional id of the acceptance criterion that cannot be met."
          },
          "evidence": {
            "type": "array",
            "minItems": 1,
            "description": "What you ran or read that establishes the blocker. At least one must match a receipt from this turn.",
            "items": {
              "type": "object",
              "properties": {
                "command": {
                  "type": "string",
                  "description": "A command you ran this turn, exactly as it ran. A command that failed is evidence too."
                },
                "paths": {
                  "type": "array",
                  "items": {
                    "type": "string"
                  },
                  "description": "Files you read or wrote this turn."
                }
              }
            }
          }
        },
        "required": [
          "blocker",
          "evidence"
        ]
      }
    },
    {
      "id": "tool:await_user",
      "kind": "tool",
      "name": "await_user",
      "description": "Hand control back to the user with the task list still open, when what the current item needs next is something only they can give: their view on what you just…",
      "status": "ready",
      "read_only": true,
      "input_schema": {
        "type": "object",
        "properties": {
          "step_id": {
            "type": "string",
            "description": "The task-list item that is waiting. Defaults to the list's current in_progress item."
          },
          "need": {
            "type": "string",
            "description": "One short line: what you need from the user before this item can go on, written to them. Not the options and not the substance — those go in your reply, or in ask when they are choices."
          }
        },
        "required": [
          "need"
        ]
      }
    },
    {
      "id": "tool:update_goal",
      "kind": "tool",
      "name": "update_goal",
      "description": "Report this turn's disposition for the active goal.",
      "status": "ready",
      "read_only": true,
      "input_schema": {
        "type": "object",
        "properties": {
          "status": {
            "type": "string",
            "enum": [
              "continue",
              "complete",
              "blocked"
            ],
            "description": "continue = keep working autonomously; complete = the goal is fully done and verified; blocked = only the user can unblock."
          },
          "reason": {
            "type": "string",
            "description": "Short explanation. REQUIRED for continue and blocked; optional for complete."
          },
          "next_action": {
            "type": "string",
            "description": "Optional concrete next step. Recommended for continue so the host can guide the next turn."
          },
          "completion": {
            "type": "object",
            "description": "Your own account of the finished work.",
            "properties": {
              "verified": {
                "type": "array",
                "items": {
                  "type": "string"
                },
                "description": "Commands you ran as proof, as they actually ran. One that never ran, failed, or predates your latest change is recorded as an unbacked claim."
              },
              "unverified": {
                "type": "array",
                "items": {
                  "type": "string"
                },
                "description": "What you did NOT verify. The host cannot infer what you skipped, so stating it is the only way it is known — and it never blocks completion."
              },
              "risks": {
                "type": "array",
                "items": {
                  "type": "string"
                },
                "description": "Known risks to carry forward."
              }
            }
          }
        },
        "required": [
          "status"
        ]
      }
    },
    {
      "id": "tool:read_only_task",
      "aliases": [
        "task:read_only_subagent"
      ],
      "kind": "tool",
      "name": "read_only_task",
      "description": "Spawn a read-only research sub-agent for a focused investigation.",
      "status": "ready",
      "read_only": true,
      "input_schema": {
        "type": "object",
        "properties": {
          "prompt": {
            "type": "string",
            "description": "What the read-only sub-agent should investigate. Be specific about the evidence or summary to return — the sub-agent does not see this conversation."
          },
          "description": {
            "type": "string",
            "description": "Short label for the read-only sub-task (3-7 words). Surfaced in the dispatch line so the user sees what's running."
          },
          "tools": {
            "type": "array",
            "items": {
              "type": "string"
            },
            "description": "Optional read-only tool whitelist. Writer, installer, memory mutation, background job, and delegation tools are never exposed."
          },
          "max_steps": {
            "type": "integer",
            "description": "Optional cap on tool-call rounds. Defaults to half the parent's cap (min 5).",
            "minimum": 1
          },
          "model": {
            "type": "string",
            "description": "Optional model override for the sub-agent (a configured provider/model name)."
          },
          "effort": {
            "type": "string",
            "description": "Optional reasoning effort for the sub-agent (e.g. high, max)."
          }
        },
        "required": [
          "prompt"
        ]
      }
    },
    {
      "id": "tool:context_budget",
      "kind": "tool",
      "name": "context_budget",
      "description": "Report how much context room is left before this conversation is automatically compacted.",
      "status": "ready",
      "read_only": true,
      "input_schema": {
        "type": "object",
        "additionalProperties": false,
        "properties": {}
      }
    }
  ],
  "note": "Call action=call with a returned capability id. An empty matches array means this catalog search found no lexical match; it does not prove that every possible external capability is unavailable.",
  "query": "conclude blocked report task cannot be done"
}", "type": "text"}, "type": "content"}]
